create table wksp_dtesc.sgt_ip_adm (
    id              number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    interface_id    number,
    ip              varchar2(45 byte),
    mask            varchar2(45 byte),
    gw              varchar2(45 byte),
    estado          varchar2(50 byte),
    creado_el       timestamp(6),
    actualizado_el  timestamp(6),
    actualizado_por varchar2(255 byte),
    creado_por      varchar2(255 byte)
);

alter table wksp_dtesc.sgt_ip_adm add primary key ( id )
    using index enable;


